from fractions import Fraction as Q
import hashlib,itertools,json,resource,time
resource.setrlimit(resource.RLIMIT_CPU,(59,60));resource.setrlimit(resource.RLIMIT_AS,(512*1024**2,)*2);start=time.monotonic()
job=json.loads(Path('research/classification/jobs/plane_scalar_t_nonzero_root_readback_v2.json').read_text())
for x in job['exact_inputs_and_hashes']:assert hashlib.sha256(Path(x['path']).read_bytes()).hexdigest()==x['sha256'],x['path']
