def checkv(cert,v,label):
 K=[[Q(v)for v in row]for row in cert['complete_kernel']];n=len(K);free=[i for i in range(n)if i not in cert['minor_columns']];assert len(free)==cert['nullity'];assert all(K[free[i]][j]==Q(i==j)for i in range(len(free))for j in range(len(free)))
 assert [sum(row[j]*v[free[j]]for j in range(len(free)))for row in K]==v,label;checks.append(label)
def vec(n,terms):
 v=[Q(0)]*n
 for i,c in terms.items():v[i]=Q(c)
 return v
for i,c in enumerate(f['cases']):assert dim(c)=={0:(8,3),3:(16,6),4:(7,0)}.get(i,(6,0))
for offset in [0,9]:
 for label,terms in [('R0',{2:1}),('R1',{0:3,4:1}),('R2',{1:2,5:1}),('R3',{0:-2,8:1})]:checkv(f['cases'][0]['D1'],vec(30,{offset+i:c for i,c in terms.items()}),'N3 '+label+' normal'+str(offset))
for i in range(3):checkv(f['cases'][0]['D2'],vec(9,{i:1}),'N3 fullD2 ab'+str(i))
checkv(f['cases'][4]['D1'],vec(30,{1:-1,5:-1,24:1}),'N2nil extra completeR')
one_roots=0;inside_nonrigid=[]
for i,c in enumerate(o['cases']):
 a=c['analysis'];assert dim(a)==(6,0)
 for w in a['all_exceptional_roots']:
  one_roots+=1
  if w['outside_declared_Jordan_domain']:continue
  p=Q(w['parameter'])
  expected=(7,0)if i==0 and p in[Q(2,3),Q(-2,3)]else(8,3)if i==2 and p in[Q(0),Q(-1)]else(6,0);assert dim(w)==expected
  if expected!=(6,0):inside_nonrigid.append(dict(source=i,parameter=str(p),kernel_dimensions=list(expected)))
  if i==0 and p in[Q(2,3),Q(-2,3)]:checkv(w['D1'],vec(30,{20 if p>0 else 29:1}),'repeatedSS extra '+str(p))
  if i==2 and p in[Q(0),Q(-1)]:
   r=4 if p==0 else 2;pairbase=3 if p==0 else 0
   for offset in [0,9]:checkv(w['D1'],vec(30,{offset+r:1}),'zeroEigenSS extra '+str(p)+' normal'+str(offset))
   for k in range(3):checkv(w['D2'],vec(9,{pairbase+k:1}),'zeroEigenSS fullD2 '+str(p)+' coeff'+str(k))
assert one_roots==20
assert dim(t['generic'])==(6,0);assert len(t['all_irreducible_linear_factors'])==12
tworoots=outside=0;lines=0
